import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/care_entities.dart';
class CareLogEditorScreen extends ConsumerStatefulWidget{const CareLogEditorScreen({super.key});@override ConsumerState<CareLogEditorScreen> createState()=>_CareLogEditorScreenState();}
class _CareLogEditorScreenState extends ConsumerState<CareLogEditorScreen>{final title=TextEditingController(),note=TextEditingController(),value=TextEditingController();String type='Feeding',unit='';@override void dispose(){title.dispose();note.dispose();value.dispose();super.dispose();}
Future<void> save()async{final p=ref.read(appControllerProvider).selectedPet;if(p==null||title.text.trim().isEmpty)return;final e=CareLog(id:DateTime.now().microsecondsSinceEpoch.toString(),petId:p.id,type:type,title:title.text.trim(),at:DateTime.now(),value:double.tryParse(value.text),unit:unit,note:note.text.trim());await ref.read(appControllerProvider).save('care_logs',e.toMap());if(mounted)Navigator.pop(context);}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Log care')),body:ListView(padding:const EdgeInsets.all(20),children:[DropdownButtonFormField<String>(value:type,decoration:const InputDecoration(labelText:'Entry type'),items:['Weight','Feeding','Activity','Grooming','Training','Behavior observation','Vet visit','Vaccination','Preventive care','Medication administered (owner-recorded)','Custom'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>type=v!)),const SizedBox(height:12),TextField(controller:title,decoration:const InputDecoration(labelText:'What happened? *')),const SizedBox(height:12),Row(children:[Expanded(child:TextField(controller:value,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount / value (optional)'))),const SizedBox(width:8),SizedBox(width:90,child:TextField(onChanged:(v)=>unit=v,decoration:const InputDecoration(labelText:'Unit')))]),const SizedBox(height:12),TextField(controller:note,maxLines:4,decoration:const InputDecoration(labelText:'Notes (optional)')),const SizedBox(height:10),const Text('Entries are owner-recorded and are not medically verified.'),const SizedBox(height:20),FilledButton(onPressed:save,child:const Text('Save entry'))]));}
